package in.anumati.platform.notification; import java.time.*;import java.util.*;public record NotificationResponse(UUID id,String type,String title,String body,String entityType,UUID entityId,Instant readAt,Instant createdAt){static NotificationResponse from(Notification n){return new NotificationResponse(n.getId(),n.getType(),n.getTitle(),n.getBody(),n.getEntityType(),n.getEntityId(),n.getReadAt(),n.getCreatedAt());}}
